public static string Main(){if(Application.isPlaying||EditorSceneManager.GetActiveScene().isDirty)throw new Exception("Clean Edit required");var setup=EditorSceneManager.GetSceneManagerSetup();var report=new JArray();try{foreach(var name in new[]{"StartRegionSandbox","OpenWorldSandbox"}){var scene=EditorSceneManager.OpenScene("Assets/EternalSteam/Scene/Tests/"+name+".unity");var v=UnityEngine.Object.FindFirstObjectByType<CanvasWorldHud>().Sandbox.RailwayHud.GetComponent<RailwayOverview>();if(v==null||v.Services!=null)throw new Exception("Expected existing 06A only");var rail=v.Railway;var s=v.gameObject.AddComponent<RailwayServicePanel>();v.Services=s;s.Overview=v;s.Root=Node("CargoAndDefense",v.Root);s.Scroll=Node("ServiceScroll",s.Root);var scroll=s.Scroll.gameObject.AddComponent<UnityEngine.UI.ScrollRect>();scroll.horizontal=false;scroll.vertical=true;scroll.scrollSensitivity=30;scroll.movementType=UnityEngine.UI.ScrollRect.MovementType.Clamped;var viewport=Node("Viewport",s.Scroll);Fill(viewport);var im=viewport.gameObject.AddComponent<UnityEngine.UI.Image>();im.color=new Color(.04f,.09f,.1f,.8f);viewport.gameObject.AddComponent<UnityEngine.UI.Mask>();scroll.viewport=viewport;var content=Node("Content",viewport);content.anchorMin=new Vector2(0,1);content.anchorMax=Vector2.one;content.sizeDelta=Vector2.zero;scroll.content=content;Stack(content);s.Cargo=Node("Cargo",content);Stack(s.Cargo);s.Defense=Node("Defense",content);Stack(s.Defense);s.CargoSummary=Text("CargoSummary",s.Cargo,rail.Title);var actions=new System.Collections.Generic.List<RailwayOverview.Action>();
void Action(string cmd,string label,Transform parent){actions.Add(new RailwayOverview.Action{Command=cmd,Button=Button(label,parent,cmd,s)});}
Action("next-stop","다음 역 선택",s.Cargo);
foreach(var item in new[]{(rail.Resource,"자원 ID · 최초 적용 후 변경 불가"),(rail.Load,"적재 수량"),(rail.Unload,"하역 수량")}){var label=Text(item.Item1.name+"Label",s.Cargo,rail.Title,item.Item2);Height(label.gameObject,30);var field=item.Item1;field.transform.SetParent(s.Cargo,false);field.transform.localScale=Vector3.one;Height(field.gameObject,40);foreach(var t in field.GetComponentsInChildren<TMP_Text>(true)){t.fontSize=18;t.enableAutoSizing=false;}field.textComponent.rectTransform.offsetMin=new Vector2(6,2);field.textComponent.rectTransform.offsetMax=new Vector2(-6,-2);}
