s.Actions=actions.ToArray();s.Return=Button("운행 화면으로",s.Root,"overview",s);s.Feedback=Text("ServiceFeedback",s.Root,rail.Title);s.Feedback.overflowMode=TextOverflowModes.Ellipsis;s.Root.gameObject.SetActive(false);EditorUtility.SetDirty(v);EditorUtility.SetDirty(rail);EditorUtility.SetDirty(s);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Save failed");report.Add(new JObject{{"scene",name},{"savedActions",s.Actions.Length},{"sameInputReferences",rail.Resource.transform.parent==s.Cargo}});}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}File.WriteAllText("Docs/Measurements/2026-10-02-hud-06b/author.json",report.ToString());return report.ToString();}}
